	function HasWildcard([string]$x) { return ($null -ne $x) -and ($x.IndexOfAny(@('*')) -ge 0) }
	
	function Fast-Copy
	{
		param (
			[Parameter(Mandatory)]
			[string]$Source,
			[Parameter(Mandatory)]
			[string]$Destination,
			[string]$Include
		)
		Write-Host " "
		Write-Host "Copying files with FastCopy..."
		Write-Host "______________________________"
		Write-Host "Source: $Source"
		Write-Host "Destination: $Destination"
		
		if (HasWildcard($Source))
		{
				$resolved = @(Get-ChildItem -Path $Source -Directory -ErrorAction SilentlyContinue | ForEach-Object { $_.FullName })
				
				foreach ($src in $resolved)
			{
					$proc = Start-Process -FilePath .\resources\fcpyPortable.exe -ArgumentList "/speed=full /no_ui /force_close /no_confirm_del /balloon=FALSE /force_start ""$src"" /to=""$Destination""" -PassThru
					$proc.WaitForExit()
				}
			}
			elseif($Include)
			{
				$proc = Start-Process -FilePath .\resources\fcpyPortable.exe -ArgumentList "/speed=full /no_ui /force_close /no_confirm_del /balloon=FALSE /force_start /include=""$Include"" ""$Source"" /to=""$Destination""" -PassThru
				$proc.WaitForExit()
			}
			else
			{
				$proc = Start-Process -FilePath .\resources\fcpyPortable.exe -ArgumentList "/speed=full /no_ui /force_close /no_confirm_del /balloon=FALSE /force_start ""$Source"" /to=""$Destination""" -PassThru
				$proc.WaitForExit()
			}
		Write-Host "Copy finished"
		Write-Host " "
	}
	
