	function Get-FileVB
	{
		param (
			[Parameter(Mandatory = $true)]
			$url,
			$destination,
			[switch]$includeStats
			
		)
		Add-Type –AssemblyName Microsoft.VisualBasic
		
		[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
		$MozillaAgent = "User-Agent: Mozilla/5.0 (compatible; NetcraftSurveyAgent/1.0; +info@netcraft.com)"
		
		$request = [System.Net.WebRequest]::Create($url)
		$request.UserAgent = $MozillaAgent
		
		$response = $request.GetResponse()
		
		$url = $response.ResponseUri.OriginalString
		$response.Close()
		$net = New-Object Microsoft.VisualBasic.Devices.Network
		$start = Get-Date
		
		$net.DownloadFile($url, $destination, '', '', $true, 500, [Microsoft.VisualBasic.FileIO.UICancelOption]::DoNothing)
		$elapsed = ((Get-Date) – $start).ToString('hh\:mm\:ss')
		$totalSize = Get-Childitem -file $destination | select length
		
		[PSCustomObject]@{ Name = "STALKER GAMMA Downloader"; TotalSize = $totalSize; Time = $elapsed }
		Get-Item $destination | Unblock-File
	}
	
	function GetModdbLinkCurl
	{
		param (
			[Parameter(Mandatory = $true)]
			$url,
			$tmp,
			$output
		)
		# get addon download page respose with url 
		
		.\resources\curl-impersonate-win\curl.exe -s --config ".\resources\curl-impersonate-win\config\safari15_5.config" --header "@resources\curl-impersonate-win\config\safari15_5.header" -o $tmp $url
		
		$link = Select-String 'window.location.href=".*' $tmp | %{ $_ -replace '.*href="', '' } | %{ $_ -replace '".*', '' }
		
		$mirror = GetMirror
		LogWrite "	Best mirror picked: $mirror"
		$link_dl = $link | %{ $_ -replace '/.../', "/$mirror/" }
		
		LogWrite "  Retrieved link: $link_dl"
		Write-Host " "
		Write-Host "=== Downloading $output ==="
		.\resources\curl-impersonate-win\curl.exe --config ".\resources\curl-impersonate-win\config\safari15_5.config" --header "@resources\curl-impersonate-win\config\safari15_5.header" -o $output $link_dl
	}
	
	function DownloadFile($url, $targetFile)
	{
		$path= $targetFile
		Get-FileVB $url $path
	}
	
	function GetDirectDownloadLink
	{
		[CmdletBinding()]
		param (
			[Parameter(Mandatory = $true, ValueFromPipeline = $true)]
			[string]$Url
		)
		
		$trimmed = .\resources\stalker-gamma-dl-cli.exe "$Url" | select -last 1
		
		if ($trimmed -match "dbolical")
		{
			LogWrite "	Retrieved ModDB link succesfully"
		}
		else
		{
			LogWrite "	Failed at retrieving ModDB link..."
			$trimmed = " "
		}
		
		return $trimmed
	}
	
	function DownloadModdbMod
	{
		param (
			[Parameter(Mandatory = $true)]
			$link_dl,
			$output
		)
		Write-Host " "
		Write-Host "=== Downloading $output ==="
		#Write-Host "    Retrieved Link: $link_dl"
		.\resources\curl-impersonate-win\curl.exe --config ".\resources\curl-impersonate-win\config\safari15_5.config" --header "@resources\curl-impersonate-win\config\safari15_5.header" -o $output "$link_dl"
	}
	
	function GetMirror()
	{
		$WebClient = New-Object System.Net.WebClient
		$WebClient.DownloadFile("https://stalker-gamma.com/api/mirrors", "$dir/mirrors.txt")
		Get-Content $dir/mirrors.txt | %{ $_ -replace 'Under heavy load.*', '' } | Sort-Object { [double]$_.split()[-2] } | ? { $_.trim() -ne "" } | Select-Object -First 3 | Get-Random | ForEach-Object { $_.Split("`t") | Select -Index 1 }
	}
	
	function Clean-Folder
	{
		param (
			[string]$rootfolder,
			[string[]]$excluded
		)
		$rootfolder = resolve-path $rootfolder
		Push-Location $rootFolder
		if ($excluded -notmatch "^\s*$")
		{
			$excluded = Resolve-Path $excluded
		}
		$filesToDel = Get-ChildItem $rootFolder -Recurse
		foreach ($exclusion in $excluded)
		{
			$filesToDel = $filesToDel | ?{ $_.fullname -notlike ("{0}\*" -f $exclusion) }
			while ($exclusion -notmatch "^\s*$")
			{
				$filesToDel = $filesToDel | ?{ $_.fullname -ne $exclusion }
				$exclusion = Split-Path -parent $exclusion
			}
		}
		$filesToDel | Remove-Item -Recurse -ErrorAction SilentlyContinue
		Pop-Location
	}
	
	function CheckGAMMAData
	{
		[Net.ServicePointManager]::SecurityProtocol = "Tls12, Tls11, Tls, Ssl3"
		$richtextbox1.Text = ""
