		$richtextbox1.AppendText("   G.A.M.M.A. addons status:  ")
		$richtextbox2.SelectionColor = "ButtonFace"
		$richtextbox2.AppendText("ModDB addons status:  ")
		if (Test-Path -Path "$dir/version.txt")
		{
			$file = "$dir/version.txt"
			$installed_version = Get-Content $file
			
			DownloadFile https://raw.githubusercontent.com/Grokitach/Stalker_GAMMA/main/G.A.M.M.A_definition_version.txt $dir/online_version.txt
			$file = "$dir/online_version.txt"
			$online_version = Get-Content $file
			
			if ($installed_version -eq $online_version)
			{
				$richtextbox1.SelectionColor = "Lime"
				$richtextbox1.AppendText("up-to-date")
				$NeedUpdate = "0"
				rm $dir/online_version.txt
			}
			else
			{
				$richtextbox1.SelectionColor = "Orange"
				$richtextbox1.AppendText("update available") 
				$NeedUpdate = "1"
				rm $dir/online_version.txt
			}
		}
		else
		{
			$richtextbox1.SelectionColor = "Orange"
			$richtextbox1.AppendText("version file not found")
			$NeedUpdate = "1"
		}
		
		if (Test-Path -Path "$dir/mods.txt")
		{
			$modshash = get-filehash "$dir/mods.txt" -algorithm md5 | %{ $_ -replace ';', '' } | %{ $_ -replace '.*Hash=', '' } | %{ $_ -replace ' .*', '' } | %{ $_.ToLower() }
			
			$WebClient = New-Object System.Net.WebClient
			$key = $textbox2.Text
			$key = $key.replace(' ', '')
			$WebClient.DownloadFile("https://stalker-gamma.com/api/client/v1/mods/list?key=$key", "$dir/mods_to_check.txt")
			$modstocheckhash = get-filehash "$dir/mods_to_check.txt" -algorithm md5 | %{ $_ -replace ';', '' } | %{ $_ -replace '.*Hash=', '' } | %{ $_ -replace ' .*', '' } | %{ $_.ToLower() }
	
			if ($modshash -eq $modstocheckhash)
			{
				$richtextbox2.SelectionColor = "Lime"
				$richtextbox2.AppendText("up-to-date")
				$NeedModDBUpdate = "0"
			}
			else
			{
				$richtextbox2.SelectionColor = "Orange"
				$richtextbox2.AppendText("update available")
				$NeedModDBUpdate = "1"
			}
		}
		else
		{
			$richtextbox2.SelectionColor = "Orange"
			$richtextbox2.AppendText("version file not found")
			$NeedModDBUpdate = "1"
		}
	}
	
	function DownloadGAMMAData
