			.\git-cmd.exe "git clone https://github.com/Grokitach/gamma_large_files_v2 && exit"
			cd $dirNorm\resources\gamma_large_files_v2
			..\.\git-cmd.exe "git config  --add safe.directory '*'  && git config  core.longpaths true &&  git config  http.postBuffer 524288000 && git config  http.maxRequestBuffer 524288000 && git reset --hard HEAD && git clean -f -d && git fetch --all && git reset --hard origin/main && git checkout -f main && exit"
			cd $dirNorm
			
			cd $dirNorm\resources\gamma_large_files_v2
			..\.\git-cmd.exe "git config  --add safe.directory '*'  && git config  core.longpaths true &&  git config  http.postBuffer 524288000 && git config  http.maxRequestBuffer 524288000 && git reset --hard HEAD && git clean -f -d && git fetch --all && git reset --hard origin/main && git checkout -f main && exit"
			cd $dirNorm
		}
			
		if (Test-Path "resources\teivaz_anomaly_gunslinger")
		{
			LogWrite " Updating Gunslinger Guns by Teivaz"
			cd $dirNorm\resources\teivaz_anomaly_gunslinger
			..\.\git-cmd.exe "git config  --add safe.directory '*'  && git config  core.longpaths true &&  git config  http.postBuffer 524288000 && git config  http.maxRequestBuffer 524288000 && git reset --hard HEAD && git clean -f -d && git fetch --all && git reset --hard origin/main && git checkout -f main && exit"
			cd $dirNorm
			
			cd $dirNorm\resources\teivaz_anomaly_gunslinger
			..\.\git-cmd.exe "git config  --add safe.directory '*'  && git config  core.longpaths true &&  git config  http.postBuffer 524288000 && git config  http.maxRequestBuffer 524288000 && git reset --hard HEAD && git clean -f -d && git fetch --all && git reset --hard origin/main && git checkout -f main && exit"
			cd $dirNorm
		}
		else
		{
			LogWrite " Cloning Gunslinger Guns by Teivaz (can take some time, that's only for the first install)"
			cd $dirNorm\resources
			.\git-cmd.exe "git clone https://github.com/Grokitach/teivaz_anomaly_gunslinger && exit"
			cd $dirNorm\resources\teivaz_anomaly_gunslinger
			..\.\git-cmd.exe "git config  --add safe.directory '*'  && git config  core.longpaths true &&  git config  http.postBuffer 524288000 && git config  http.maxRequestBuffer 524288000 && git reset --hard HEAD && git clean -f -d && git fetch --all && git reset --hard origin/main && git checkout -f main && exit"
			cd $dirNorm
			
			cd $dirNorm\resources\teivaz_anomaly_gunslinger
			..\.\git-cmd.exe "git config  --add safe.directory '*'  && git config  core.longpaths true &&  git config  http.postBuffer 524288000 && git config  http.maxRequestBuffer 524288000 && git reset --hard HEAD && git clean -f -d && git fetch --all && git reset --hard origin/main && git checkout -f main && exit"
			cd $dirNorm
