	$buttonInstallUpdateGAMMA_Click = {
		[System.Windows.Forms.Application]::DoEvents()
		
		[Net.ServicePointManager]::SecurityProtocol = "Tls12, Tls11, Tls, Ssl3"
		
		If (Test-Path -Path "$dir\.modpack_installer.log")
		{
			mv "$dir\.modpack_installer.log" "$dir\.modpack_installer.log.bak" -Force
		}
		
		if (Test-Path -Path "$dir\modpack_maker_metadata.txt")
		{
		}
		else
		{
			LogWrite "	modpack_maker_metadata.txt file not found in Grok's Modpack Maker root folder, exiting."
			LogWrite "	Verify that G.A.M.M.A. Launcher.exe is in the correct folder (GAMMA/.Grok's Modpack Installer)."
			Exit
		}
		
		DownloadGAMMAData
		
		$metadata = Get-Content -Path $dir\modpack_maker_metadata.txt | %{ $_ -replace '.*= ', '' } | %{ $_ -replace '.*=', '' }
		
		$author = $metadata | Select -Index 0
		$modpack_name = $metadata | Select -Index 1
	#	$modlist_file = $metadata | Select -Index 2
		$modorganizer_modlist_file = $metadata | Select -Index 3
		$modpack_additional_files = $metadata | Select -Index 4
		
		$mo2Path = "$dir\..\"
		$mo2Path = $mo2Path
		
		$downloadsPath = "$dir\..\downloads"
		$downloadsPath = $downloadsPath
		
		
		$modsPath = "$dir\..\mods"
		$modsPath = $modsPath
		
		$modpackPath = "$dir\$modpack_name"
		$modpackPath = $modpackPath
		
		LogWrite " Downloading GAMMA mods information from www.stalker-gamma.com"
		
		$modlistPath = "$dir/mods.txt"
		
		$WebClient = New-Object System.Net.WebClient
		$key=$textbox2.Text
		$WebClient.DownloadFile("https://stalker-gamma.com/api/client/v1/mods/list?key=$key", "$modlistPath")
		
		$modlist_file = "$dir/mods.txt"
		
		$counter = 0
		
		$largefilesdownloaded = "0"
		
		$totaladdons = (Get-Content -Path $modlist_file).Length
		
		$progressbar1.Value = 0
		$progressbar1.Maximum = $totaladdons
		$windows_version = ([System.Environment]::OSVersion.Version).Major
		
		LogWrite " "
		LogWrite "=================================================================================="
		LogWrite "                        Add-ons and Separators Installation                       "
		LogWrite "=================================================================================="
		LogWrite " "
		
		If (Test-Path -Path "$downloadsPath")
		{
		}
		else { mkdir "$downloadsPath" > $null }
		
		If (Test-Path -Path "$modsPath")
		{
		}
		else { mkdir "$modsPath" > $null }
		
		$files = Get-Content -Path $modlist_file
		
		ForEach ($file in $files)
		{
			[System.Windows.Forms.Application]::DoEvents()
			$download_and_install = "0"
			$counter = $counter + 1
			$progressbar1.PerformStep()
			$DL_link = $file.Split("`t") | Select -Index 0
			$Instructions = $file.Split("`t") | Select -Index 1
			$Patch = $file.Split("`t") | Select -Index 2
			$AddonName = $file.Split("`t") | Select -Index 3
			$Moddb_URL = $file.Split("`t") | Select -Index 4
			$ZipName = $file.Split("`t") | Select -Index 5
			$MD5moddb = $file.Split("`t") | Select -Index 6
			
			If ($Patch -eq "0")
			{
				$Patch = ""
			}
			
			$moddb = Select-String -Pattern "moddb" -InputObject $DL_link
			$github = Select-String -Pattern "github" -InputObject $DL_link
			$gofile = Select-String -Pattern "gofile" -InputObject $DL_link
			$separator = Select-String -Pattern "http" -NotMatch -InputObject $DL_link
			$gamma_large_files = Select-String -Pattern "gamma_large_files" -InputObject $DL_link
			
			if ($gamma_large_files)
			{
				$github = $null
				$gofile = $null
			}
			
			if ($separator)
			{
				$Name = $separator
				$FolderName = "${Name}_separator"
				LogWrite "_______________ $Name separator _______________"
				LogWrite "	Creating MO2 separator in $modsPath\$FolderName"
				If (Test-Path -Path "$modsPath\$counter-$FolderName") { }
				else
				{
					mkdir "$modsPath\$counter-$FolderName" > $null
				}
				
				if ($windows_version -eq 10)
				{
					.\resources\Robocopy_10.exe "$dir\resources\separator" "$modsPath\$counter-$FolderName" "meta.ini"  /NFL /NDL /NJH /NJS /NC /NS /XO | Out-Null
				}
				else
				{
					.\resources\Robocopy_6.exe "$dir\resources\separator" "$modsPath\$counter-$FolderName" "meta.ini"  /NFL /NDL /NJH /NJS /NC /NS /XO | Out-Null
				}
				
				LogWrite " "
				continue
			}
			
			if ($github)
			{
				$Name = $DL_link.Split("/") | Select-Object -Index 4
				$Name = "$Name.zip"
				$DL = $DL_link
				$StartDownload = "1"
			}
			
			if ($moddb)
			{
				$Name = $ZipName
				$StartDownload = "1"
			}
			
			if ($gofile)
			{
				$Name = $DL_link.Split("/") | Select-Object -Index 6
				$Name = "$Name.zip"
				$DL = $DL_link
				$StartDownload = "1"
			}
			
			if ($gamma_large_files)
			{
				$Name = $DL_link.Split("/") | Select-Object -Index 6
				$Name = "$Name.zip"
				$DL = $DL_link
				$StartDownload = "1"
			}
			
			if ($StartDownload -eq "1")
			{
	#			if ($moddb)
	#			{
	#				if ($Name -eq $null)
	#				{
	#					$WebClient.DownloadFile($DL_link, "$dir\dl.html")
	#					$Name = Select-String 'Click to' $dir\dl.html | %{ $_ -replace '.*>download ', '' } | %{ $_ -replace '</.*', '' }
	#				}
	#			}
				
				$DL_path = "$downloadsPath\$Name"
				
				LogWrite "=== $AddonName ==="
				
				if (Test-Path -Path "$DL_path")
				{
					LogWrite "	Add-on already downloaded in $DL_path"
					
					$download_and_install = "0"
					$extract = "0"
					$gitmd5 = "0"
					
					
					if ($github)
					{
						if ($checkboxForceGitDownload.Checked)
						{
							$download_and_install = "1"
							$extract = "1"
						}
						
						if ($checkboxCheckMD5.Checked)
						{
							$md5 = get-filehash $DL_path -algorithm md5 | %{ $_ -replace ';', '' } | %{ $_ -replace '.*Hash=', '' } | %{ $_ -replace ' .*', '' } | %{ $_.ToLower() }
							if ($MD5moddb)
							{
								if ($MD5moddb -eq $md5)
								{
									LogWrite "	MD5 Hash is correct."
								}
								else
								{
									LogWrite "	MD5 Hash of local addon is not correct. Redownloading and installing."
									$gitmd5 = "1"
									$download_and_install = "1"
								}
							}
						}
					}
					
					if ($moddb)
					{
						if ($checkboxCheckMD5.Checked)
						{
							$md5 = get-filehash $DL_path -algorithm md5 | %{ $_ -replace ';', '' } | %{ $_ -replace '.*Hash=', '' } | %{ $_ -replace ' .*', '' } | %{ $_.ToLower() }
							if ($MD5moddb -eq $md5)
							{
								LogWrite "	MD5 Hash is correct."
							}
							else
							{
								LogWrite "	MD5 Hash of local addon is not correct. Redownloading and installing."
								$download_and_install = "1"
							}
						}
					}
					
					if ($gofile)
					{
						if ($checkboxCheckMD5.Checked)
						{
							$md5 = get-filehash $DL_path -algorithm md5 | %{ $_ -replace ';', '' } | %{ $_ -replace '.*Hash=', '' } | %{ $_ -replace ' .*', '' } | %{ $_.ToLower() }
							if ($MD5moddb -eq $md5)
							{
								LogWrite "	MD5 Hash is correct."
							}
							else
							{
								LogWrite "	MD5 Hash of local addon is not correct. Redownloading and installing."
								$download_and_install = "1"
							}
						}
					}
					
					if ($gamma_large_files) #and if gamma large files archive already exists
					{	
						if ($largefilesdownloaded -eq "1")
						{
							if ($checkboxUpdateLargeFiles.Checked)
							{
								LogWrite "	GitHub GAMMA Large Files found and already downloaded, installing"
								$download_and_install = "0"
								$extract = "1"
							}
							else
							{
								LogWrite "	Add-on already downloaded in $DL_path but GAMMA Large Files found, forcing extraction."
								
								$download_and_install = "0"
								$extract = "1"
							}
						}
						else
						{
							if ($checkboxUpdateLargeFiles.Checked)
							{
								LogWrite "	GitHub GAMMA Large Files found but update is forced, downloading and installing"
								$download_and_install = "1"
								$extract = "1"
							}
						}
					}
				}
				else
				{
					LogWrite "	Add-on archive not found, will download and install it"
					$download_and_install = "1"
				}
				
				if ($download_and_install -eq "1")
				{
					if ($github)
					{
						if ($checkboxForceGitDownload.Checked)
						{
							LogWrite "	GitHub link found, download is forced. Downloading to $DL_path"
							DownloadFile $DL $DL_path
							$DL_base = $DL
							$extract = "1"
						}elseif ($gitmd5 -eq "1")
						{
							DownloadFile $DL $DL_path
							$DL_base = $DL
							$extract = "1"
						}elseif ( !(Test-Path -Path "$DL_path") )
						{
							DownloadFile $DL $DL_path
							$DL_base = $DL
							$extract = "1"
						}
					}
					
					if ($gofile)
					{
						LogWrite "	Downloading to $DL_path"
						DownloadFile $DL_base $DL_path
						$DL_base = $DL
						$extract = "1"
						
						if ($checkboxCheckMD5.Checked)
						{
							$md5 = get-filehash $DL_path -algorithm md5 | %{ $_ -replace ';', '' } | %{ $_ -replace '.*Hash=', '' } | %{ $_ -replace ' .*', '' } | %{ $_.ToLower() }
							if ($MD5moddb -eq $md5)
							{
								LogWrite "	MD5 Hash is correct."
							}
							else
							{
								LogWrite "	MD5 Hash of local addon is not correct. Redownloading one more time and installing."
								LogWrite "	Downloading to $DL_path"
								#$mirror = GetMirror
								#LogWrite "	Best mirror picked: $mirror"
								$DL_base = $DL_base | %{ $_ -replace '/.../', "/$mirror/" }
								DownloadFile $DL_base $DL_path
								$extract = "1"
							}
						}
					}
					
					if ($gamma_large_files)
					{
						if ($largefilesdownloaded -eq "0")
						{
							LogWrite "	GAMMA Large files link found and not downloaded yet. Downloading to $DL_path"
							DownloadFile $DL $DL_path
							$DL_base = $DL
							$largefilesdownloaded = "1"
							$extract = "1"
						}
					}
					
					if ($moddb)
					{
						LogWrite "	Downloading $DL_link to $DL_path"
						
						#$DL_base = GetModdbDL $DL_link "$dir\dl.html"
						
						#$DL_base = GetModdbLinkCurl $DL_link "$dir\dl.html"
						#$mirror = GetMirror
						#LogWrite "	Best mirror picked: $mirror"
						#$DL_base = $link | %{ $_ -replace '/.../', "/$mirror/" }
						
						#DownloadFile $DL_base $DL_path
						
						#LogWrite "	Downloading: $DL_base"
						
						#DownloadModdbLinkCurl $DL_base $DL_path
						
						#GetModdbLinkCurl $DL_link "$dir\dl.html" $DL_path
						
						$CDN_Link = GetDirectDownloadLink $DL_link
						DownloadModdbMod $CDN_Link $DL_path
						
						$extract = "1"
						
						if ($checkboxCheckMD5.Checked)
						{
							$md5 = get-filehash $DL_path -algorithm md5 | %{ $_ -replace ';', '' } | %{ $_ -replace '.*Hash=', '' } | %{ $_ -replace ' .*', '' } | %{ $_.ToLower() }
							if ($MD5moddb -eq $md5)
							{
								LogWrite "	MD5 Hash is correct."
							}
							else
							{
								LogWrite "	MD5 Hash of local addon is not correct. Redownloading one more time and installing."
								LogWrite "	Downloading $DL_link to $DL_path"
								#$mirror = GetMirror
								#LogWrite "	Best mirror picked: $mirror"
								#$DL_base = $DL_base | %{ $_ -replace '/.../', "/$mirror/" }
								#DownloadFile $DL_base $DL_path
								
								#GetModdbLinkCurl $DL_link "$dir\dl.html" $DL_path
								
								$CDN_Link = GetDirectDownloadLink $DL_link
								DownloadModdbMod $CDN_Link $DL_path
								
								#DownloadModdbLinkCurl $DL_base $DL_path
								$extract = "1"
							}
						}
					}
				}
				
				$Extract_path = "$modsPath\$counter-$AddonName$Patch"
				
				if ($checkboxForceZipExtraction.Checked -or $extract -eq "1")
				{
					if (Test-Path -Path "$Extract_path")
					{
						LogWrite "	Deleting content of the previous version of $AddonName in $Extract_path"
						Get-ChildItem "$Extract_path" -Directory | ForEach-Object {
							Remove-Item -Force -Recurse -ErrorAction SilentlyContinue -LiteralPath $_.FullName
						}
					}
					
					LogWrite "	Extracting to $Extract_path"
					
					.\resources\7zip\7z.exe x $DL_path -aoa -o"$Extract_path"
					
					if (-not $?)
					{
						LogWrite "	Unable to extract archive because of an aborted download."
						
						LogWrite "	Downloading addon to $DL_path"
						
						if ($moddb)
						{
							#$mirror = GetMirror
							#LogWrite "	Best mirror picked: $mirror"
							#$DL_base = $DL_base | %{ $_ -replace '/.../', "/$mirror/" }
							#DownloadModdbLinkCurl $DL_base $DL_path
							#GetModdbLinkCurl $DL_link "$dir\dl.html" $DL_path
							
							$CDN_Link = GetDirectDownloadLink $DL_link
							DownloadModdbMod $CDN_Link $DL_path
						}
						else
						{
							DownloadFile $DL_base $DL_path
						}
	
						.\resources\7zip\7z.exe x $DL_path -aoa -o"$Extract_path"
					}
					
					$Full_path = (Get-ChildItem $DL_path).fullname
					
					If ($Instructions -match "^0$")
					{
						LogWrite "	No specific instructions found for this add-on"
						LogWrite "	Generating meta.ini file"
						Get-Content -Encoding utf8 resources/meta.ini | %{ $_ -replace "installationFile=.*", "installationFile=$Name" } | %{ $_ -replace "version=.*", "version=$Name" } | %{ $_ -replace "url=.*", "url=$Moddb_URL" } | %{ $_ -replace "hasCustomURL=.*", "hasCustomURL=true" } | Out-File -Encoding utf8 $Extract_path/meta.ini
						LogWrite " "
						continue
					}
					else
					{
						LogWrite "	Instructions solving..."
						$Instructions = $Instructions.Split(":")
						ForEach ($i in $Instructions)
						{
							#				copy-item -LiteralPath "\\?\$Extract_path$i" -Destination "\\?\$Extract_path" -force -recurse
							if (Test-Path -LiteralPath "$Extract_path\$i\gamedata")
							{
								if ($windows_version -eq 10)
								{
									.\resources\Robocopy_10.exe "$Extract_path\$i" "$Extract_path" /s /move *.*
								}
								else
								{
									.\resources\Robocopy_6.exe "$Extract_path\$i" "$Extract_path" /s /move *.*
								}
								LogWrite "		Copying $Extract_path\$i"
							}
							else
							{
								if ($windows_version -eq 10)
								{
									LogWrite "		gamedata folder not found, creating it"
									mkdir "$Extract_path\gamedata" -ErrorAction SilentlyContinue
									.\resources\Robocopy_10.exe "$Extract_path\$i" "$Extract_path\gamedata" /s /move *.*
								}
								else
								{
									LogWrite "		gamedata folder not found, creating it"
									mkdir "$Extract_path\gamedata" -ErrorAction SilentlyContinue
									.\resources\Robocopy_6.exe "$Extract_path\$i" "$Extract_path\gamedata" /s /move *.*
								}
								LogWrite "		Copying $Extract_path\$i"
							}
						}
						LogWrite "		Cleaning add-on folder"
						Get-ChildItem "$Extract_path" -Directory -Exclude gamedata, appdata, db, fomod | ForEach-Object {
							Remove-Item -Force -Recurse -ErrorAction SilentlyContinue -LiteralPath $_.FullName
						}
					}
					$StartDownload = "0"
					LogWrite "	Generating meta.ini file"
					Get-Content -Encoding utf8 resources/meta.ini | %{ $_ -replace "installationFile=.*", "installationFile=$Name" } | %{ $_ -replace "version=.*", "version=$Name" } | %{ $_ -replace "url=.*", "url=$Moddb_URL" } | %{ $_ -replace "hasCustomURL=.*", "hasCustomURL=true" } | Out-File -Encoding utf8 $Extract_path/meta.ini
					LogWrite " "
				}
			}
		}
		
		
		
		LogWrite " "
		LogWrite "=================================================================================="
		LogWrite "                    Installing Modpack-specific modifications                     "
		LogWrite "=================================================================================="
		LogWrite " "
		
		LogWrite "	Copying $modpackPath\$modpack_additional_files to $modsPath , installer can hang but continues working."
		
		if ($windows_version -eq 10)
		{
			.\resources\Robocopy_10.exe "$dir\resources\gamma_large_files_v2" "$modsPath" /s /xd ".git" 
		}
		else
		{
			.\resources\Robocopy_6.exe "$dir\resources\gamma_large_files_v2" "$modsPath" /s /xd ".git"
		}
	
		Fast-Copy "$dir\resources\teivaz_anomaly_gunslinger\*\gamedata" "..\mods\312- Gunslinger Guns for Anomaly - Teivazcz & Gunslinger Team\gamedata"
		Fast-Copy "$dir\resources\teivaz_anomaly_gunslinger\*\*\gamedata" "..\mods\312- Gunslinger Guns for Anomaly - Teivazcz & Gunslinger Team\gamedata"
	
		if ($windows_version -eq 10)
		{
			.\resources\Robocopy_10.exe "$dir\G.A.M.M.A\modpack_addons" "$modsPath" /s
		}
		else
		{
			.\resources\Robocopy_6.exe "$dir\G.A.M.M.A\modpack_addons" "$modsPath" /s
		}
	
		LogWrite "	Done"
		LogWrite " "
		LogWrite "=================================================================================="
		LogWrite "                             MO2 Profile Setup                                    "
		LogWrite "=================================================================================="
		LogWrite " "
		
		LogWrite "	Deleting Default Profile"
		$defaultProfilePath = "$dir\..\profiles\Default"
		If (Test-Path -Path $defaultProfilePath)
		{
			rm $defaultProfilePath -force -recurse
		}
		
		LogWrite "	Creating MO2 Profile $modpack_name"
		$gammaProfilePath = "$dir\..\profiles\$modpack_name"
		If (Test-Path -Path $gammaProfilePath)
		{
		}
		else { mkdir $gammaProfilePath > $null }
		Fast-Copy "$dir\resources\profiles_files\" "$gammaProfilePath"
		
		LogWrite "	Copying modpack modlist.txt file"
		Fast-Copy "$modpackPath\$modorganizer_modlist_file" "$gammaProfilePath" "modlist.txt"
		LogWrite "	Done"
		
		
		LogWrite " "
		LogWrite "=================================================================================="
		LogWrite "                 Patching Anomaly bin, audio and MCM preferences                  "
		LogWrite "=================================================================================="
		LogWrite " "
		
		LogWrite "	Locating Anomaly folder from ModOrganizer.ini"
		$mo2iniPath = "$dir\..\ModOrganizer.ini"
		$mo2ini = Get-Content -Path $mo2iniPath
		$AnomalyPath = Select-String -Pattern "gamePath" -InputObject $mo2ini | %{ $_ -replace "AnomalyLauncher.exe.*", '' } | %{ $_ -replace ".*binary=", '' }
		
		LogWrite "	Copying user profile, reshade files, and patched exes from $modpackPath\modpack_patches to $AnomalyPath"
		
		Fast-Copy "$modpackPath\modpack_patches\*" "$AnomalyPath"
		
		if ($checkboxDeleteReshadeDLLs.Checked)
		{
			LogWrite "	Deleting Reshade's DLLs"
			if (Test-Path "$AnomalyPath\bin\dxgi.dll")
			{
				rm "$AnomalyPath\bin\dxgi.dll"
			}
			
			if (Test-Path "$AnomalyPath\bin\d3d9.dll")
			{
				rm "$AnomalyPath\bin\d3d9.dll"
			}
		}
		
		LogWrite "	Removing shader cache"
		Remove-Item -Force -Recurse -ErrorAction SilentlyContinue $AnomalyPath\appdata\shaders_cache
		
		LogWrite "	Done"
		LogWrite " "
		LogWrite "=================================================================================="
		LogWrite "           Creating Shortcut to the modpack MO2 instance on the desktop           "
		LogWrite "=================================================================================="
		LogWrite " "
		
		$WshShell = New-Object -comObject WScript.Shell
		$Shortcut = $WshShell.CreateShortcut("$Home\Desktop\G.A.M.M.A. Launcher.lnk")
		$path_to_use = Resolve-Path "$dir\G.A.M.M.A. Launcher.exe" | select -ExpandProperty Path
		$Shortcut.TargetPath = $path_to_use
		$icon_path = Resolve-Path "$modpackPath\modpack_data\modpack_icon.ico" | select -ExpandProperty Path
		$Shortcut.IconLocation = $icon_path
		$Shortcut.Save()
		
		$WshShell = New-Object -comObject WScript.Shell
		$Shortcut = $WshShell.CreateShortcut("$Home\Desktop\G.A.M.M.A..lnk")
		$path_to_use = "$dir\..\ModOrganizer.exe"
		$path_to_use = Resolve-Path $path_to_use | select -ExpandProperty Path
		$Shortcut.TargetPath = $path_to_use
		$icon_path = Resolve-Path "$modpackPath\modpack_data\modpack_icon.ico" | select -ExpandProperty Path
		$Shortcut.IconLocation = $icon_path
		$Shortcut.Save()
		
		LogWrite "Installation complete. You can now click Play"
		LogWrite " "
		LogWrite "Want to support the author of this modpack? Buy me a coffee <3 https://paypal.me/GrokitachGAMMA"
		LogWrite " "
		
		#$WebClient.DownloadFile("https://test.stalker-gamma.com/api/client/v1/mods/list?key=$key", "$dir/mods.txt")
		CheckGAMMAData
	}
	
